SourceCode.Declaration:
/// <summary>
/// One warehouse's turn at the posting queue: a task HSMobileOpsProcessPendingBatch adds to itself
/// for each warehouse with Pending rows, so warehouses post side by side. The work is
/// HSMobileOpsPostingService::processWarehouse.
/// </summary>
class HSMobileOpsPostingWorker extends RunBaseBatch
{
    DataAreaId       company;
    InventLocationId warehouse;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        company,
        warehouse
    #endmacro
}

Method.Source:
public static HSMobileOpsPostingWorker newTask(DataAreaId _company, InventLocationId _warehouse)
{
    HSMobileOpsPostingWorker worker = new HSMobileOpsPostingWorker();

    worker.parmCompany(_company);
    worker.parmWarehouse(_warehouse);
    worker.batchInfo().parmCaption(strFmt('Mobile ops: post %1 %2', _company, _warehouse));
    return worker;
}

public DataAreaId parmCompany(DataAreaId _company = company)
{
    company = _company;
    return company;
}

public InventLocationId parmWarehouse(InventLocationId _warehouse = warehouse)
{
    warehouse = _warehouse;
    return warehouse;
}

public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            return true;
    }
    return false;
}

public static ClassDescription description()
{
    return 'Mobile ops: post one warehouse';
}
